{"content": [{"type": "text", "text": "{
  "id": 394282,
  "name": "HasDimension",
  "source_text": "/-- A quantity of type `M` which depends on a choice of units `UnitChoices` is said to be\n  of dimension `d` if it scales by `UnitChoices.dimScale u1 u2 d` under a change in units. -/\ndef HasDimension {M : Type} [CarriesDimension M] (f : UnitChoices → M) : Prop :=\n  ∀ u1 u2 : UnitChoices, f u2 = UnitChoices.dimScale u1 u2 (dim M) • f u1\n"
}"}], "structured_content": {"result": {"id": 394282, "name": "HasDimension", "source_text": "/-- A quantity of type `M` which depends on a choice of units `UnitChoices` is said to be
  of dimension `d` if it scales by `UnitChoices.dimScale u1 u2 d` under a change in units. -/
def HasDimension {M : Type} [CarriesDimension M] (f : UnitChoices → M) : Prop :=
  ∀ u1 u2 : UnitChoices, f u2 = UnitChoices.dimScale u1 u2 (dim M) • f u1
"}}}

